mapper.select:
SELECT l.user_id AS userId, u.nickname AS userName, COUNT(*) AS requestCount, IFNULL(SUM(l.total_tokens), 0) AS totalTokens FROM ai_usage_log l LEFT JOIN sys_user u ON l.user_id = u.user_id WHERE l.status = 1 AND YEAR(l.create_time) = YEAR(CURDATE()) AND MONTH(l.create_time) = MONTH(CURDATE())
AND l.create_time >= #{startTime}
AND l.create_time <= CONCAT(#{endTime}, ' 23:59:59')
GROUP BY l.user_id, u.nickname ORDER BY totalTokens DESC LIMIT #{limit}
